package com.aicharacter.v3;import org.json.JSONObject;
public final class CreatureState {public String id="reedling_amber_01",objectId="reedling_01",preferredArea="lakeside";public OrganismBodyState body=new OrganismBodyState();public OrganismSenseState sense=new OrganismSenseState();public OrganismCycleState cycle=new OrganismCycleState();public double trustHaru=.08,trustCat=.02,fear=.28,hunger=.35,energy=.75,relationPressure=.0,migrationIntent=.0;public float x=1450;public String areaId="lakeside",activity="wander",ecologyTargetAreaId="";public long lastUpdate;public int encountersHaru,encountersCat;public long lastEncounter;
 public void meetHaru(boolean calm,long now){encountersHaru++;trustHaru=Math.min(1,trustHaru+(calm?.045:.015));fear=Math.max(0,fear-.025);lastEncounter=now;}public void meetCat(boolean calm,long now){encountersCat++;trustCat=Math.min(1,trustCat+(calm?.03:.008));fear=Math.max(0,fear-(calm?.015:0));lastEncounter=now;}
 public JSONObject toJson(){JSONObject j=new JSONObject();try{j.put("id",id);j.put("objectId",objectId);j.put("preferredArea",preferredArea);j.put("trustHaru",trustHaru);j.put("trustCat",trustCat);j.put("fear",fear);j.put("hunger",hunger);j.put("encountersHaru",encountersHaru);j.put("encountersCat",encountersCat);j.put("lastEncounter",lastEncounter);j.put("energy",energy);j.put("relationPressure",relationPressure);j.put("migrationIntent",migrationIntent);j.put("ecologyTargetAreaId",ecologyTargetAreaId);j.put("body",body.toJson());j.put("sense",sense.toJson());j.put("cycle",cycle.toJson());j.put("x",x);j.put("areaId",areaId);j.put("activity",activity);j.put("lastUpdate",lastUpdate);}catch(Exception ignored){}return j;}
 public static CreatureState fromJson(JSONObject j){CreatureState c=new CreatureState();if(j!=null){c.id=j.optString("id",c.id);c.objectId=j.optString("objectId",c.objectId);c.preferredArea=j.optString("preferredArea",c.preferredArea);c.trustHaru=j.optDouble("trustHaru",c.trustHaru);c.trustCat=j.optDouble("trustCat",c.trustCat);c.fear=j.optDouble("fear",c.fear);c.hunger=j.optDouble("hunger",c.hunger);c.encountersHaru=j.optInt("encountersHaru");c.encountersCat=j.optInt("encountersCat");c.lastEncounter=j.optLong("lastEncounter");c.energy=j.optDouble("energy",c.energy);c.relationPressure=Math.max(0,Math.min(1,j.optDouble("relationPressure",c.relationPressure)));c.migrationIntent=Math.max(0,Math.min(1,j.optDouble("migrationIntent",c.migrationIntent)));c.ecologyTargetAreaId=j.optString("ecologyTargetAreaId","");c.body=OrganismBodyState.fromJson(j.optJSONObject("body"));c.sense=OrganismSenseState.fromJson(j.optJSONObject("sense"));c.cycle=OrganismCycleState.fromJson(j.optJSONObject("cycle"));c.x=(float)j.optDouble("x",c.x);c.areaId=j.optString("areaId",c.areaId);c.activity=j.optString("activity",c.activity);c.lastUpdate=j.optLong("lastUpdate");}return c;}
}
